-- The first twenty themed challenges, 2026-09-24, with 365 daily to-dos each.
-- Generated from data/challenges.json by tools/challenges_sql.py --since 2026-09-24;
-- an upsert on slug, so applying it twice is harmless.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('slowing-down-the-mental-chatter', 'Slowing Down the Mental Chatter', 'For the days when your mind will not stop talking. Each day gives you one small way to notice the noise, let it pass, and come back to what is in front of you.', 'Mindfulness', 365, array['Mindfulness', 'Stress']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('fostering-gratitude', 'Fostering Gratitude', 'A daily habit of noticing what is already good, even on hard days. Each day points you at one small thing to appreciate, say thank you for, or savor a little longer.', 'Gratitude', 365, array['Resilience', 'Mindfulness']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('redirecting-unhelpful-thoughts', 'Redirecting Unhelpful Thoughts', 'For thoughts that run in circles, jump to the worst case, or talk you down. Each day offers one practical way to catch an unhelpful thought and steer it somewhere more useful.', 'Thinking', 365, array['Thinking Traps', 'CBT']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('winding-down-for-better-sleep', 'Winding Down for Better Sleep', 'Small evening changes that make it easier to drift off. Each day asks for one adjustment to the last hour of your day, so sleep has a clearer path to find you.', 'Sleep', 365, array['Sleep', 'Habits']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('softening-the-inner-critic', 'Softening the Inner Critic', 'For anyone who talks to themselves more harshly than they would ever talk to a friend. Each day gives you one way to notice the critical voice and answer it with something kinder and more honest.', 'Self-Compassion', 365, array['Self-Compassion', 'Self-Esteem']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('moving-a-little-every-day', 'Moving a Little Every Day', 'Gentle daily movement for people who do not want a workout plan, just a body that feels a little looser and a mood that feels a little lighter. Every day is one small, doable way to move.', 'Body', 365, array['Movement', 'Body']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('reaching-out-to-people', 'Reaching Out to People', 'For when your circle has gone quiet or you have been keeping to yourself. Each day is one small, low-pressure way to reconnect with someone, so contact becomes easier again.', 'Connection', 365, array['Relationships', 'Loneliness']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('loosening-the-grip-of-worry', 'Loosening the Grip of Worry', 'For a mind that spends its days rehearsing what could go wrong. Each day gives you one way to set worry down for a while, so it takes up less of your day.', 'Worry', 365, array['Worry', 'Anxiety']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('holding-your-boundaries', 'Holding Your Boundaries', 'For people who say yes when they mean no, or feel used up by everyone else''s needs. Each day is one small practice in noticing your limits and stating them plainly and kindly.', 'Boundaries', 365, array['Boundaries', 'Assertiveness']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('building-a-calmer-morning', 'Building a Calmer Morning', 'For mornings that start with a scramble and set the tone for the whole day. Each day is one small change to the first hour, so you begin from somewhere steadier.', 'Mornings', 365, array['Habits', 'Stress']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('making-room-for-rest', 'Making Room for Rest', 'For people who are running on empty and cannot remember the last real break. Each day gives you one small permission to stop, so rest becomes part of the day instead of something you earn.', 'Rest', 365, array['Burnout', 'Self-Care']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('living-by-your-values', 'Living by Your Values', 'For when your days are full but do not feel like yours. Each day asks you to notice what matters to you and take one small action in that direction, so your life lines up a little more with what you care about.', 'Values', 365, array['Values', 'Motivation']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('small-acts-of-kindness', 'Small Acts of Kindness', 'A daily practice of doing something small for someone else, which has a way of lifting the giver too. Each day is one easy, specific act of kindness, most of them taking less than five minutes.', 'Kindness', 365, array['Relationships', 'Values']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('making-peace-with-time-alone', 'Making Peace with Time Alone', 'For when being on your own feels more like emptiness than freedom. Each day offers one small way to make time alone feel chosen, full, and kind, while keeping the door open to other people.', 'Loneliness', 365, array['Loneliness', 'Self-Care']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('loosening-the-phone-habit', 'Loosening the Phone Habit', 'For anyone who picks up their phone without deciding to and puts it down feeling worse. Each day is one small experiment in using the phone on purpose, so your attention comes back to you.', 'Focus', 365, array['Habits', 'Mindfulness']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('tidying-one-corner-at-a-time', 'Tidying One Corner at a Time', 'For a home that has gotten on top of you and a mind that feels the same. Each day is one small corner, drawer, or surface, ten minutes at most, so order comes back a little at a time.', 'Home', 365, array['Habits', 'Stress']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('meeting-anger-early', 'Meeting Anger Early', 'For anger that arrives fast and leaves a mess behind. Each day gives you one way to notice it sooner, cool it a little, and say what you mean without the heat, one practice at a time.', 'Anger', 365, array['Anger', 'Emotion Regulation']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('rebuilding-confidence-in-small-steps', 'Rebuilding Confidence in Small Steps', 'For when your confidence has taken a knock and everything feels like a risk. Each day is one small, doable act of showing up, so evidence that you can builds one day at a time.', 'Confidence', 365, array['Self-Esteem', 'Social Anxiety']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('feeling-your-feet-on-the-ground', 'Feeling Your Feet on the Ground', 'For the moments when everything speeds up and you feel far away from yourself. Each day teaches one simple grounding practice, so you have a toolkit ready when you need to come back to the present.', 'Grounding', 365, array['Grounding', 'Anxiety']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz),
  ('getting-unstuck-one-tiny-step-at-a-time', 'Getting Unstuck, One Tiny Step at a Time', 'For the task you keep putting off and the guilt that grows around it. Each day asks for one tiny, specific step on something you have been avoiding, so momentum comes back without needing a burst of willpower.', 'Motivation', 365, array['Motivation', 'Perfectionism']::text[], 1, '2026-09-24T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('slowing-down-the-mental-chatter', 'fostering-gratitude', 'redirecting-unhelpful-thoughts', 'winding-down-for-better-sleep', 'softening-the-inner-critic', 'moving-a-little-every-day', 'reaching-out-to-people', 'loosening-the-grip-of-worry', 'holding-your-boundaries', 'building-a-calmer-morning', 'making-room-for-rest', 'living-by-your-values', 'small-acts-of-kindness', 'making-peace-with-time-alone', 'loosening-the-phone-habit', 'tidying-one-corner-at-a-time', 'meeting-anger-early', 'rebuilding-confidence-in-small-steps', 'feeling-your-feet-on-the-ground', 'getting-unstuck-one-tiny-step-at-a-time');

insert into public.challenge_days (template_id, day, title, task)
select t.id, v.day, null, v.task
from (values
  ('slowing-down-the-mental-chatter', 1, 'Sit for two minutes and count your breaths from one to ten. When you lose count, start again at one.'),
  ('slowing-down-the-mental-chatter', 2, 'Pick one ordinary sound near you, a fan, traffic, birds, and listen to it alone for one full minute.'),
  ('slowing-down-the-mental-chatter', 3, 'Each time a thought pulls you away today, silently label it "thinking" and return to what you were doing.'),
  ('slowing-down-the-mental-chatter', 4, 'Eat one meal or snack with nothing else going on. Notice the taste of the first three bites.'),
  ('slowing-down-the-mental-chatter', 5, 'Set a timer for three minutes and watch your thoughts go by as if they were cars on a road. You are on the sidewalk.'),
  ('slowing-down-the-mental-chatter', 6, 'Walk for five minutes and name what you see, in your head, as you pass it: tree, mailbox, door.'),
  ('slowing-down-the-mental-chatter', 7, 'Before you reply to any message today, take one slow breath first.'),
  ('slowing-down-the-mental-chatter', 8, 'Write down the thought that keeps circling. Seeing it on paper often shrinks it.'),
  ('slowing-down-the-mental-chatter', 9, 'Do one chore, dishes, folding, sweeping, at half your usual speed and stay with the movements.'),
  ('slowing-down-the-mental-chatter', 10, 'Notice the pause at the end of each out-breath. Rest there for a second before the next breath comes.'),
  ('slowing-down-the-mental-chatter', 11, 'Choose a word like "steady" or "here." Say it silently on each out-breath for two minutes.'),
  ('slowing-down-the-mental-chatter', 12, 'Stand at a window for three minutes and simply look. No phone, no plan, just looking.'),
  ('slowing-down-the-mental-chatter', 13, 'When your mind races today, feel your feet on the floor and press them down gently for ten seconds.'),
  ('slowing-down-the-mental-chatter', 14, 'Put your hand on your chest and feel it rise and fall for ten breaths.'),
  ('slowing-down-the-mental-chatter', 15, 'Give your mind one job for five minutes: count backward from 100 by threes.'),
  ('slowing-down-the-mental-chatter', 16, 'Drink a glass of water slowly, noticing the temperature and the swallow.'),
  ('slowing-down-the-mental-chatter', 17, 'Spend three minutes noticing five things you can see, four you can hear, and three you can touch.'),
  ('slowing-down-the-mental-chatter', 18, 'When a worry loop starts, ask it: "Is there anything to do about this right now?" If not, let it wait until tomorrow.'),
  ('slowing-down-the-mental-chatter', 19, 'Do a two-minute body scan from head to feet, just noticing, not fixing.'),
  ('slowing-down-the-mental-chatter', 20, 'Take a shower or wash your hands and put all your attention on the water.'),
  ('slowing-down-the-mental-chatter', 21, 'Sit with a cup of something warm and do nothing else until it is finished.'),
  ('slowing-down-the-mental-chatter', 22, 'Repeat one line of a song, a poem, or a prayer slowly, three times, and notice how your mind settles.'),
  ('slowing-down-the-mental-chatter', 23, 'Set an hourly reminder and take three conscious breaths each time it goes off.'),
  ('slowing-down-the-mental-chatter', 24, 'Look at one small object, a leaf, a coin, a pen, for two full minutes as if you had never seen one.'),
  ('slowing-down-the-mental-chatter', 25, 'Notice when you are rehearsing a conversation in your head and gently drop the script.'),
  ('slowing-down-the-mental-chatter', 26, 'Lie on the floor for five minutes and feel the ground holding you up.'),
  ('slowing-down-the-mental-chatter', 27, 'Stretch your arms overhead and breathe out with a long, audible sigh. Do it three times.'),
  ('slowing-down-the-mental-chatter', 28, 'Spend five minutes coloring, doodling, or tracing shapes without trying to make anything.'),
  ('slowing-down-the-mental-chatter', 29, 'Before bed, write down three things your mind is holding for tomorrow so it can put them down tonight.'),
  ('slowing-down-the-mental-chatter', 30, 'Sit quietly for five minutes and, whenever a thought appears, say to yourself "not now" and return to your breath.'),
  ('slowing-down-the-mental-chatter', 31, 'Open a window or step onto the porch and listen to the outdoors for two minutes, naming each sound as it arrives.'),
  ('slowing-down-the-mental-chatter', 32, 'Brush your teeth tonight with all your attention on the bristles, the taste, and the sound.'),
  ('slowing-down-the-mental-chatter', 33, 'Fold one piece of laundry so slowly that you notice the warmth and texture of the fabric.'),
  ('slowing-down-the-mental-chatter', 34, 'Count ten steps on your way to the mailbox, the car, or the kitchen, feeling each foot land.'),
  ('slowing-down-the-mental-chatter', 35, 'Trace the outline of your hand with one finger and notice how the chatter quiets while you do it.'),
  ('slowing-down-the-mental-chatter', 36, 'Pause at a red light or a crosswalk and take one breath that goes all the way down to your belly.'),
  ('slowing-down-the-mental-chatter', 37, 'Hum a single note on a long out-breath and feel it vibrate in your chest.'),
  ('slowing-down-the-mental-chatter', 38, 'Peel an orange or an apple slowly and give your full attention to the smell and the peel.'),
  ('slowing-down-the-mental-chatter', 39, 'Rinse a dish and watch the water run over it until the last bubble is gone.'),
  ('slowing-down-the-mental-chatter', 40, 'Sit in your car for one minute before turning the key and just breathe.'),
  ('slowing-down-the-mental-chatter', 41, 'Wait in line today without reaching for anything. Notice what your mind does with the empty minute.'),
  ('slowing-down-the-mental-chatter', 42, 'Rest your gaze on a cloud and follow it until it changes shape or slides out of view.'),
  ('slowing-down-the-mental-chatter', 43, 'Watch a candle flame or a lamp glow for three minutes and let your thoughts drift past it.'),
  ('slowing-down-the-mental-chatter', 44, 'Feel the weight of your body in a chair for ten breaths, letting the chair do the holding.'),
  ('slowing-down-the-mental-chatter', 45, 'Let a pot of coffee or tea brew without checking anything else. Stay with the smell until it is ready.'),
  ('slowing-down-the-mental-chatter', 46, 'Notice one thought that arrives, and instead of following it, imagine placing it on a shelf for later.'),
  ('slowing-down-the-mental-chatter', 47, 'Type or write one sentence more slowly than usual, feeling each key or each stroke of the pen.'),
  ('slowing-down-the-mental-chatter', 48, 'Stand in the shower for one extra minute and count the sensations of water on your shoulders.'),
  ('slowing-down-the-mental-chatter', 49, 'Pick one color and spend two minutes finding it everywhere in the room around you.'),
  ('slowing-down-the-mental-chatter', 50, 'Chew a piece of gum or a raisin for a full minute before swallowing, noticing every change in texture.'),
  ('slowing-down-the-mental-chatter', 51, 'Say the alphabet backward silently, one letter per breath, and notice the quiet it leaves behind.'),
  ('slowing-down-the-mental-chatter', 52, 'Sweep or vacuum one room while keeping your attention on the sound of the tool against the floor.'),
  ('slowing-down-the-mental-chatter', 53, 'Sit with a pet, a plant, or a view for three minutes and match your breath to something slow in front of you.'),
  ('slowing-down-the-mental-chatter', 54, 'Turn off the car radio for one drive and simply notice the road, the sky, and the hum of the engine.'),
  ('slowing-down-the-mental-chatter', 55, 'Water a plant slowly and watch the soil darken as it drinks.'),
  ('slowing-down-the-mental-chatter', 56, 'Tie your shoes with your full attention, feeling the laces and the tug of the knot.'),
  ('slowing-down-the-mental-chatter', 57, 'Notice a thought about the future today and gently ask yourself what is true right now instead.'),
  ('slowing-down-the-mental-chatter', 58, 'Rest one palm on a cool surface, a counter, a window, a table, and feel it for thirty seconds.'),
  ('slowing-down-the-mental-chatter', 59, 'Read a single paragraph out loud, slowly, and listen to your own voice as if it belonged to someone else.'),
  ('slowing-down-the-mental-chatter', 60, 'Spend two minutes noticing the space between objects instead of the objects themselves.'),
  ('slowing-down-the-mental-chatter', 61, 'Lean against a wall and feel it take some of your weight for ten breaths.'),
  ('slowing-down-the-mental-chatter', 62, 'Sit outside at dusk and watch the light change until you notice the first shadow disappear.'),
  ('slowing-down-the-mental-chatter', 63, 'Write one busy thought on a scrap of paper and drop it in the recycling.'),
  ('slowing-down-the-mental-chatter', 64, 'Stir a pot, a cup, or a bowl in slow circles and let your attention follow the spoon.'),
  ('slowing-down-the-mental-chatter', 65, 'Listen to one song with your eyes closed and try to follow a single instrument all the way through.'),
  ('slowing-down-the-mental-chatter', 66, 'Take the stairs slowly today and count each step under your breath.'),
  ('slowing-down-the-mental-chatter', 67, 'Notice the moment your mind starts a to-do list and take one breath before writing anything down.'),
  ('slowing-down-the-mental-chatter', 68, 'Put both feet flat on the ground during a meeting or a call and press them into the floor while you listen.'),
  ('slowing-down-the-mental-chatter', 69, 'Rub your palms together until they warm and then rest them over your closed eyes for five breaths.'),
  ('slowing-down-the-mental-chatter', 70, 'Look up at the sky for one minute and name three colors you can see in it.'),
  ('slowing-down-the-mental-chatter', 71, 'Set your phone face down for one meal today and notice how many times your hand reaches for it.'),
  ('slowing-down-the-mental-chatter', 72, 'Stand still in the middle of a busy place, a store, a hallway, a sidewalk, and simply watch for one minute.'),
  ('slowing-down-the-mental-chatter', 73, 'Breathe in for a count of four and out for a count of six, ten times, before you open your email.'),
  ('slowing-down-the-mental-chatter', 74, 'Notice the sound your feet make on different surfaces today: carpet, tile, gravel, grass.'),
  ('slowing-down-the-mental-chatter', 75, 'Carry a small stone or a smooth object in your pocket and touch it whenever the chatter picks up.'),
  ('slowing-down-the-mental-chatter', 76, 'Draw one slow line across a page and let your breath match the pace of the pen.'),
  ('slowing-down-the-mental-chatter', 77, 'Sit with a dog, a cat, or a bird and watch how it rests without thinking about tomorrow.'),
  ('slowing-down-the-mental-chatter', 78, 'Say "this is just a thought" the next time a story starts to play in your head.'),
  ('slowing-down-the-mental-chatter', 79, 'Feel the sun or the wind on your face for one full minute without adding a single word to it.'),
  ('slowing-down-the-mental-chatter', 80, 'Notice when you are reading the same sentence twice and pause for three breaths before you go on.'),
  ('slowing-down-the-mental-chatter', 81, 'Hold a warm mug with both hands and feel the heat move into your fingers for ten breaths.'),
  ('slowing-down-the-mental-chatter', 82, 'Spend five minutes pulling weeds, raking, or shoveling and stay with the rhythm of the work.'),
  ('slowing-down-the-mental-chatter', 83, 'Look at your reflection in a window or a mirror and take three slow breaths without judging what you see.'),
  ('slowing-down-the-mental-chatter', 84, 'Walk to the end of the block and back with your hands in your pockets, noticing only the ground.'),
  ('slowing-down-the-mental-chatter', 85, 'Wash one window or mirror slowly and watch it clear, stroke by stroke.'),
  ('slowing-down-the-mental-chatter', 86, 'Listen for the quietest sound in the room and rest your attention on it for one minute.'),
  ('slowing-down-the-mental-chatter', 87, 'Notice a thought that starts with "what if" and let it float past without answering it.'),
  ('slowing-down-the-mental-chatter', 88, 'Sit on the floor with your back against the couch and feel the support along your spine for five breaths.'),
  ('slowing-down-the-mental-chatter', 89, 'Choose a doorway you pass often and take one slow breath every time you walk through it today.'),
  ('slowing-down-the-mental-chatter', 90, 'Squeeze a pillow, a stress ball, or your own hand, then release, and feel the difference for ten seconds.'),
  ('slowing-down-the-mental-chatter', 91, 'Count the seconds between a car passing and the next one and notice how your mind fills the gap.'),
  ('slowing-down-the-mental-chatter', 92, 'Notice a rushing feeling in your body today and slow one movement, any movement, by half.'),
  ('slowing-down-the-mental-chatter', 93, 'Smell something simple, coffee, soap, cut grass, rain, and stay with it for five breaths.'),
  ('slowing-down-the-mental-chatter', 94, 'Sit on a bench or a step and watch people pass without inventing a story about any of them.'),
  ('slowing-down-the-mental-chatter', 95, 'Lie in bed for two minutes before getting up and feel the weight of the blanket.'),
  ('slowing-down-the-mental-chatter', 96, 'Watch the steam rise from a hot drink or a pot until it thins out and vanishes.'),
  ('slowing-down-the-mental-chatter', 97, 'Put one hand on your belly and one on your chest and notice which one moves more as you breathe.'),
  ('slowing-down-the-mental-chatter', 98, 'Follow the sound of a plane, a train, or a siren from the moment you notice it until it is gone.'),
  ('slowing-down-the-mental-chatter', 99, 'Spend one minute noticing the texture of the clothes against your skin.'),
  ('slowing-down-the-mental-chatter', 100, 'Give your next chore a soundtrack of nothing: no music, no podcast, just the sound of the work.'),
  ('slowing-down-the-mental-chatter', 101, 'Before your first sip of anything this morning, take three breaths and notice the quiet before the day starts talking.'),
  ('slowing-down-the-mental-chatter', 102, 'Open the fridge, pause, and notice one thing you had never really looked at before you grab what you came for.'),
  ('slowing-down-the-mental-chatter', 103, 'Sit on the edge of the bed tonight and let your shoulders drop on three long out-breaths.'),
  ('slowing-down-the-mental-chatter', 104, 'Notice how many tabs are open in your mind right now and close one by writing it on a sticky note.'),
  ('slowing-down-the-mental-chatter', 105, 'Scrub one pan by hand and give the whole job to your fingertips.'),
  ('slowing-down-the-mental-chatter', 106, 'Unlock the front door slowly this evening and take one breath on the threshold before stepping in.'),
  ('slowing-down-the-mental-chatter', 107, 'Walk barefoot across one room and feel every change in the floor under your feet.'),
  ('slowing-down-the-mental-chatter', 108, 'Catch yourself mid-sentence in an imaginary argument and let the other person have the last word.'),
  ('slowing-down-the-mental-chatter', 109, 'Stand in the grocery aisle and notice three colors on the shelf before you reach for anything.'),
  ('slowing-down-the-mental-chatter', 110, 'Cut a vegetable slowly and listen to the sound of the knife on the board.'),
  ('slowing-down-the-mental-chatter', 111, 'Notice the first bird or the first car you hear this morning and follow the sound until it fades.'),
  ('slowing-down-the-mental-chatter', 112, 'Take one slow breath each time you sit down today, before you do anything else in the chair.'),
  ('slowing-down-the-mental-chatter', 113, 'Rest your forehead on your folded arms at a table for one minute and let the room go quiet.'),
  ('slowing-down-the-mental-chatter', 114, 'Ask your mind to say the next thought out loud, then notice the pause while it decides.'),
  ('slowing-down-the-mental-chatter', 115, 'Watch rain, snow, or leaves fall for three minutes and let each one land without commentary.'),
  ('slowing-down-the-mental-chatter', 116, 'Sip a glass of cold water and follow the coolness as far down as you can feel it.'),
  ('slowing-down-the-mental-chatter', 117, 'Notice where your tongue is resting right now and let it soften off the roof of your mouth.'),
  ('slowing-down-the-mental-chatter', 118, 'Stretch your fingers wide, hold for five seconds, then let them go limp and notice the release.'),
  ('slowing-down-the-mental-chatter', 119, 'Pull up a chair to a window at lunch and eat while watching whatever is out there.'),
  ('slowing-down-the-mental-chatter', 120, 'Turn a doorknob, a faucet, or a light switch slowly today and feel the mechanism move.'),
  ('slowing-down-the-mental-chatter', 121, 'Practice one minute of silence in the car before you go into work or the store.'),
  ('slowing-down-the-mental-chatter', 122, 'Listen to the hum of the refrigerator or the heater for one minute and let it be the only thing.'),
  ('slowing-down-the-mental-chatter', 123, 'Notice a thought that keeps returning today and greet it by name, "oh, that one again," before you let it go.'),
  ('slowing-down-the-mental-chatter', 124, 'Put your hands in warm dishwater and stay there for ten breaths before you start washing.'),
  ('slowing-down-the-mental-chatter', 125, 'Look at a tree for two minutes and try to see one leaf move at a time.'),
  ('slowing-down-the-mental-chatter', 126, 'Pat a dog, a cat, or a soft blanket and give the whole two minutes to your hand.'),
  ('slowing-down-the-mental-chatter', 127, 'Sit in a parked car with the engine off and count twenty breaths before you go in.'),
  ('slowing-down-the-mental-chatter', 128, 'Notice the exact moment a bite of food loses its flavor and only then take the next one.'),
  ('slowing-down-the-mental-chatter', 129, 'Feel your feet inside your shoes right now and wiggle your toes for ten seconds.'),
  ('slowing-down-the-mental-chatter', 130, 'Stand outside for one minute tonight and count the stars or the lights you can see.'),
  ('slowing-down-the-mental-chatter', 131, 'Put down whatever is in your hands, rest them on your thighs, and take five breaths with nothing to hold.'),
  ('slowing-down-the-mental-chatter', 132, 'Notice a story your mind is telling about someone today and ask what you actually saw or heard.'),
  ('slowing-down-the-mental-chatter', 133, 'Open a book at random and read one sentence slowly, three times, letting the meaning settle.'),
  ('slowing-down-the-mental-chatter', 134, 'Sit at a table and slide one object, a cup, a pen, a coin, back and forth for one minute with all your attention.'),
  ('slowing-down-the-mental-chatter', 135, 'Feel the seams of a chair or a couch with your fingertips and let your breath slow as you trace them.'),
  ('slowing-down-the-mental-chatter', 136, 'Let the kettle, the microwave, or the coffee maker finish without walking away, watching the clock instead.'),
  ('slowing-down-the-mental-chatter', 137, 'Choose one hallway or path you walk daily and cover it today at half speed.'),
  ('slowing-down-the-mental-chatter', 138, 'Bring your attention to the sound of your own footsteps on the way in from the car.'),
  ('slowing-down-the-mental-chatter', 139, 'Listen to the wind, or the absence of it, for one minute from wherever you are.'),
  ('slowing-down-the-mental-chatter', 140, 'Squint at a light source, a lamp, a window, a screen, and notice the shapes the blur makes for thirty seconds.'),
  ('slowing-down-the-mental-chatter', 141, 'Notice one worry that belongs to next week and place it in an imaginary envelope marked "not today."'),
  ('slowing-down-the-mental-chatter', 142, 'Sit through one commercial, one loading screen, or one elevator ride without filling the gap.'),
  ('slowing-down-the-mental-chatter', 143, 'Rock gently side to side in a chair for one minute and let your breath follow the motion.'),
  ('slowing-down-the-mental-chatter', 144, 'Feel the pull of gravity on your arms by letting them hang heavy at your sides for ten breaths.'),
  ('slowing-down-the-mental-chatter', 145, 'Look at the ceiling for one minute and let your eyes rest on nothing in particular.'),
  ('slowing-down-the-mental-chatter', 146, 'Chop, stir, or pour while saying the action silently, "chopping, chopping," to keep your mind in the kitchen.'),
  ('slowing-down-the-mental-chatter', 147, 'Sit in a waiting room today and count the breaths between one person entering and the next.'),
  ('slowing-down-the-mental-chatter', 148, 'Trace a circle on your palm with one finger, slowly, ten times.'),
  ('slowing-down-the-mental-chatter', 149, 'Stand at the sink after dinner and notice how the room sounds once the dishes are done.'),
  ('slowing-down-the-mental-chatter', 150, 'Watch a cat, a squirrel, or a bird go about its business and let it set the pace of your breathing.'),
  ('slowing-down-the-mental-chatter', 151, 'Notice a rehearsal for tomorrow''s meeting starting in your head and give tomorrow permission to wait.'),
  ('slowing-down-the-mental-chatter', 152, 'Take three breaths with your eyes closed before you turn on any screen this morning.'),
  ('slowing-down-the-mental-chatter', 153, 'Fold a paper in half, then in half again, slowly, and feel the crease under your thumb.'),
  ('slowing-down-the-mental-chatter', 154, 'Feel the difference between the air inside and outside as you step through a door today.'),
  ('slowing-down-the-mental-chatter', 155, 'Hold a piece of ice or run cold water over your wrists and give your full attention to the sensation until it fades.'),
  ('slowing-down-the-mental-chatter', 156, 'Sit still through one song from start to finish without changing it, skipping it, or looking anything up.'),
  ('slowing-down-the-mental-chatter', 157, 'Notice the sound of your own breathing when you lie down tonight and count ten of them.'),
  ('slowing-down-the-mental-chatter', 158, 'Let one question go unanswered today. Notice the urge to look it up and let it pass.'),
  ('slowing-down-the-mental-chatter', 159, 'Walk around the block after dinner and name the smells you pass: cut grass, smoke, a neighbor''s cooking.'),
  ('slowing-down-the-mental-chatter', 160, 'Put your hand on a tree trunk and feel the bark for ten breaths.'),
  ('slowing-down-the-mental-chatter', 161, 'Feel the air move through your nostrils, cool on the way in, warmer on the way out, for two minutes.'),
  ('slowing-down-the-mental-chatter', 162, 'Hang laundry, stack dishes, or put away groceries with each item getting your full attention.'),
  ('slowing-down-the-mental-chatter', 163, 'Turn off every light in one room tonight and sit in the dark for three minutes.'),
  ('slowing-down-the-mental-chatter', 164, 'Whisper the word "slow" on your next five out-breaths and see what your shoulders do.'),
  ('slowing-down-the-mental-chatter', 165, 'Notice how loud your mind is on a scale of one to ten this morning, and check again tonight without trying to change it.'),
  ('slowing-down-the-mental-chatter', 166, 'Sit on the porch, a stoop, or a step with a warm drink at dawn and watch the street wake up.'),
  ('slowing-down-the-mental-chatter', 167, 'Blink slowly ten times and notice the tiny rest your eyes get each time they close.'),
  ('slowing-down-the-mental-chatter', 168, 'Pick a single word, "leaf," "wind," "cup," and repeat it silently until it sounds like nothing but a sound.'),
  ('slowing-down-the-mental-chatter', 169, 'Let a phone call or a video end and sit in the quiet for one minute before you move on.'),
  ('slowing-down-the-mental-chatter', 170, 'Press your thumb into the center of your other palm and hold it for ten breaths.'),
  ('slowing-down-the-mental-chatter', 171, 'Build a snowman, rake a pile of leaves, or plant a seed, and let the task be the only thing on your mind while you do it.'),
  ('slowing-down-the-mental-chatter', 172, 'Notice the sound of a fan or an air conditioner on a hot afternoon and let it wash over you for one minute.'),
  ('slowing-down-the-mental-chatter', 173, 'Shovel a path, scrape a windshield, or salt a step, slowly, and feel the cold on your cheeks instead of the list in your head.'),
  ('slowing-down-the-mental-chatter', 174, 'Pull a sweater over your head this fall and pause inside it for one breath before your head comes through.'),
  ('slowing-down-the-mental-chatter', 175, 'Watch a bee, a butterfly, or an ant for two minutes and let its busy path replace your own for a while.'),
  ('slowing-down-the-mental-chatter', 176, 'Lie in the grass or on a blanket in a park and watch the clouds until your mind is as slow as they are.'),
  ('slowing-down-the-mental-chatter', 177, 'Crunch through fallen leaves on purpose and give each step your full hearing.'),
  ('slowing-down-the-mental-chatter', 178, 'Sit by a fire, a heater, or a sunny window this winter and feel the warmth reach your hands before anything else.'),
  ('slowing-down-the-mental-chatter', 179, 'Bite into something crisp, an apple, a cracker, a carrot, and listen to the sound inside your own head.'),
  ('slowing-down-the-mental-chatter', 180, 'Notice your mind narrating a walk, a meal, or a drive today and see if you can just take the walk instead.'),
  ('slowing-down-the-mental-chatter', 181, 'Watch the ripples spread when you drop a pebble in a puddle or a pond, all the way to the edge.'),
  ('slowing-down-the-mental-chatter', 182, 'Feel the heat of a summer sidewalk through your shoes for ten steps.'),
  ('slowing-down-the-mental-chatter', 183, 'Catch a snowflake or a raindrop on your sleeve and watch it until it disappears.'),
  ('slowing-down-the-mental-chatter', 184, 'Sit under a tree in full leaf and count the different shades of green you can find.'),
  ('slowing-down-the-mental-chatter', 185, 'Wrap your hands around a cold drink on a hot day and notice the condensation on your fingers.'),
  ('slowing-down-the-mental-chatter', 186, 'Walk through a farmers market, a fair, or a store and notice smells before you notice prices.'),
  ('slowing-down-the-mental-chatter', 187, 'Turn your face toward the first warm day of spring and take five slow breaths through your nose.'),
  ('slowing-down-the-mental-chatter', 188, 'Notice a thought about what someone thinks of you and let it drift past like a leaf on a stream.'),
  ('slowing-down-the-mental-chatter', 189, 'Sit through the ten seconds before a meeting starts without checking anything.'),
  ('slowing-down-the-mental-chatter', 190, 'Feel the pen or the mouse in your hand at your desk and loosen your grip by half.'),
  ('slowing-down-the-mental-chatter', 191, 'Take one breath before you open each door at work today.'),
  ('slowing-down-the-mental-chatter', 192, 'Listen to a coworker, a friend, or a family member for one full minute without planning your reply.'),
  ('slowing-down-the-mental-chatter', 193, 'Walk to the printer, the restroom, or the break room at half speed and notice what you pass.'),
  ('slowing-down-the-mental-chatter', 194, 'Sit at your desk with both hands in your lap for one minute before you start the next task.'),
  ('slowing-down-the-mental-chatter', 195, 'Notice the moment your mind jumps ahead to the next item on the agenda and bring it back to the sentence being spoken.'),
  ('slowing-down-the-mental-chatter', 196, 'Eat lunch away from your screen today and look at something farther than arm''s length while you chew.'),
  ('slowing-down-the-mental-chatter', 197, 'Stretch your neck side to side between tasks and feel the muscles lengthen for five breaths.'),
  ('slowing-down-the-mental-chatter', 198, 'Look out the nearest window between emails and find one thing that is moving.'),
  ('slowing-down-the-mental-chatter', 199, 'Let your inbox sit unopened for the first ten minutes of your day and breathe instead.'),
  ('slowing-down-the-mental-chatter', 200, 'Rest your eyes on the far wall for thirty seconds every time you finish a task this afternoon.'),
  ('slowing-down-the-mental-chatter', 201, 'Feel the chair beneath you the next time someone else is talking in a meeting.'),
  ('slowing-down-the-mental-chatter', 202, 'Notice the hum of the building, the lights, the vents, the computers, and let it be background for one minute.'),
  ('slowing-down-the-mental-chatter', 203, 'Wash your coffee cup at work slowly and completely before you refill it.'),
  ('slowing-down-the-mental-chatter', 204, 'Stand up, roll your shoulders three times, and take one long exhale before you sit back down.'),
  ('slowing-down-the-mental-chatter', 205, 'Walk to your car or the bus stop tonight without headphones and listen to the evening.'),
  ('slowing-down-the-mental-chatter', 206, 'Cook one dish tonight and give each ingredient your full attention as it goes in the pan.'),
  ('slowing-down-the-mental-chatter', 207, 'Sit down to dinner and take three breaths before you pick up your fork.'),
  ('slowing-down-the-mental-chatter', 208, 'Clear the table one plate at a time, feeling the weight of each one.'),
  ('slowing-down-the-mental-chatter', 209, 'Turn the volume down on the television or the music by a notch and notice how your body settles.'),
  ('slowing-down-the-mental-chatter', 210, 'Notice a thought about the day''s mistakes and set it on the counter, like a set of keys, until tomorrow.'),
  ('slowing-down-the-mental-chatter', 211, 'Read one page of a book before bed and go back to the first line if your mind has wandered.'),
  ('slowing-down-the-mental-chatter', 212, 'Lie on your back tonight and let each part of your body sink into the mattress, one at a time, from toes to head.'),
  ('slowing-down-the-mental-chatter', 213, 'Wipe down a counter in slow strokes and let the motion carry your attention.'),
  ('slowing-down-the-mental-chatter', 214, 'Notice the exact temperature of the room as you lie in bed, cool or warm, and stay with it for ten breaths.'),
  ('slowing-down-the-mental-chatter', 215, 'Turn your phone to silent an hour before bed and notice how the room sounds without it.'),
  ('slowing-down-the-mental-chatter', 216, 'Sit on the stairs for one minute between one floor and the next with nothing to do.'),
  ('slowing-down-the-mental-chatter', 217, 'Pick up a pinecone, a shell, a feather, or a stone on a walk and study it for two full minutes.'),
  ('slowing-down-the-mental-chatter', 218, 'Feel your heartbeat in your fingertips by pressing them gently against your wrist for one minute.'),
  ('slowing-down-the-mental-chatter', 219, 'Notice when your mind says "hurry" and ask it, quietly, "hurry to where?"'),
  ('slowing-down-the-mental-chatter', 220, 'Write down the loudest thought of the morning and check tonight whether it still needs you.'),
  ('slowing-down-the-mental-chatter', 221, 'Let one worry finish its sentence, then say "noted" and return to your hands.'),
  ('slowing-down-the-mental-chatter', 222, 'Match your breath to the swing of a door, the tick of a clock, or the drip of a faucet for one minute.'),
  ('slowing-down-the-mental-chatter', 223, 'Stand on one foot for thirty seconds and notice how the chatter fades when your balance needs you.'),
  ('slowing-down-the-mental-chatter', 224, 'Look at a photo of a place you have been and stay with just the colors for one minute.'),
  ('slowing-down-the-mental-chatter', 225, 'Notice a plan forming for something a month away and gently return to the cup, the road, or the page in front of you.'),
  ('slowing-down-the-mental-chatter', 226, 'Follow a single raindrop down a window from top to bottom.'),
  ('slowing-down-the-mental-chatter', 227, 'Take three slow breaths before you answer the phone the next time it rings.'),
  ('slowing-down-the-mental-chatter', 228, 'Listen to a piece of music with no words and follow the quietest part.'),
  ('slowing-down-the-mental-chatter', 229, 'Notice one thing in your kitchen you have never really looked at and give it two minutes.'),
  ('slowing-down-the-mental-chatter', 230, 'Sit with your back straight and your eyes half closed for three minutes and count the sounds that come and go.'),
  ('slowing-down-the-mental-chatter', 231, 'Feel the shape of your own breath in your nose, cool in, warm out, while you wait for anything today.'),
  ('slowing-down-the-mental-chatter', 232, 'Move one object in your home to a new spot and notice how many times your mind comments on it.'),
  ('slowing-down-the-mental-chatter', 233, 'Give your next glass of water, juice, or milk your complete attention from the first sip to the last.'),
  ('slowing-down-the-mental-chatter', 234, 'Sit in a different chair than usual for five minutes and notice what the room looks like from there.'),
  ('slowing-down-the-mental-chatter', 235, 'Notice a memory that starts to replay and let the picture fade before it reaches its usual ending.'),
  ('slowing-down-the-mental-chatter', 236, 'Stand at the top of a hill, a staircase, or a bridge and take five breaths while looking at the widest view you can find.'),
  ('slowing-down-the-mental-chatter', 237, 'Repeat a slow "in" on each inhale and "out" on each exhale, silently, for two minutes.'),
  ('slowing-down-the-mental-chatter', 238, 'Hold a leaf, a petal, or a blade of grass up to the light and study the lines running through it.'),
  ('slowing-down-the-mental-chatter', 239, 'Notice how your hands feel after washing them and let that be the whole moment.'),
  ('slowing-down-the-mental-chatter', 240, 'Close your eyes on a bench, in a waiting room, or at your desk, and count five breaths before opening them.'),
  ('slowing-down-the-mental-chatter', 241, 'Notice one sound that repeats, a clock, a dripping tap, a bird, and count ten of its beats.'),
  ('slowing-down-the-mental-chatter', 242, 'Feel the rim of a glass or a mug with your lip before you drink and notice the temperature first.'),
  ('slowing-down-the-mental-chatter', 243, 'Take a slow walk through your own home as if you were a guest seeing it for the first time.'),
  ('slowing-down-the-mental-chatter', 244, 'Sit with a friend or a family member in comfortable silence for two minutes and notice how it feels.'),
  ('slowing-down-the-mental-chatter', 245, 'Notice the pull to explain yourself in your head after a conversation and let the explanation stay unsaid.'),
  ('slowing-down-the-mental-chatter', 246, 'Fill a sink or a bowl with warm water and simply rest your hands in it for two minutes.'),
  ('slowing-down-the-mental-chatter', 247, 'Look at a single word on a page until it stops looking like a word.'),
  ('slowing-down-the-mental-chatter', 248, 'Rest a hand on a sleeping pet, a sleeping child, or your own knee and feel the stillness under it.'),
  ('slowing-down-the-mental-chatter', 249, 'Walk up a flight of stairs and pause at the top for three breaths before you go on with the day.'),
  ('slowing-down-the-mental-chatter', 250, 'Pay attention to the moment a thought ends and notice the small gap before the next one.'),
  ('slowing-down-the-mental-chatter', 251, 'Stand in the doorway of a room you have just finished cleaning and take one long breath.'),
  ('slowing-down-the-mental-chatter', 252, 'Watch a ceiling fan, a spinning wheel, or a mobile for one minute and let your eyes go soft.'),
  ('slowing-down-the-mental-chatter', 253, 'Sip hot chocolate, cider, or tea on a cold night and follow the warmth all the way down.'),
  ('slowing-down-the-mental-chatter', 254, 'Sit on a park bench in spring and count how many different birds you can hear in three minutes.'),
  ('slowing-down-the-mental-chatter', 255, 'Pick one word you hear often today, "okay," "yes," "thanks," and notice each time it lands.'),
  ('slowing-down-the-mental-chatter', 256, 'Hold a door for someone and use the pause to take one full breath.'),
  ('slowing-down-the-mental-chatter', 257, 'Notice a thought that judges how well you are doing this practice and let it be just another thought.'),
  ('slowing-down-the-mental-chatter', 258, 'Rock a chair, sway on your feet, or bounce your knee slowly and let the rhythm hold your attention.'),
  ('slowing-down-the-mental-chatter', 259, 'Feel the fabric of the sheets against your feet for ten breaths before you get out of bed.'),
  ('slowing-down-the-mental-chatter', 260, 'Drive one familiar route with the window cracked and notice the change in air at each turn.'),
  ('slowing-down-the-mental-chatter', 261, 'Let a text or an email sit unanswered for ten minutes and notice the urge to reply rise and fall.'),
  ('slowing-down-the-mental-chatter', 262, 'Take a sip of soup, broth, or tea and hold it in your mouth for three seconds before swallowing.'),
  ('slowing-down-the-mental-chatter', 263, 'Notice your jaw right now and let it unclench for ten breaths.'),
  ('slowing-down-the-mental-chatter', 264, 'Watch a pot of water come to a boil from the first bubble to the rolling ones.'),
  ('slowing-down-the-mental-chatter', 265, 'Stand at a bus stop, a train platform, or a curb and count the colors of the passing cars.'),
  ('slowing-down-the-mental-chatter', 266, 'Pull a blanket over your knees on a cool evening and feel the warmth build under it.'),
  ('slowing-down-the-mental-chatter', 267, 'Notice a thought comparing today to yesterday and return to what today actually looks like.'),
  ('slowing-down-the-mental-chatter', 268, 'Lean back in a chair, look at the ceiling, and take ten breaths with nothing else on the schedule.'),
  ('slowing-down-the-mental-chatter', 269, 'Run your fingers along a bookshelf, a fence, or a railing and feel each change in texture.'),
  ('slowing-down-the-mental-chatter', 270, 'Sit in the quiet after a loud moment, a slammed door, a siren, a dropped pan, and let your body settle.'),
  ('slowing-down-the-mental-chatter', 271, 'Peel back a corner of the day by noticing one thing you did not see yesterday on your usual route.'),
  ('slowing-down-the-mental-chatter', 272, 'Feel the difference between your left hand and your right for one minute, without moving either.'),
  ('slowing-down-the-mental-chatter', 273, 'Chew each bite of one meal until it is completely soft before you swallow.'),
  ('slowing-down-the-mental-chatter', 274, 'Take the long way to the mailbox, the trash, or the car and notice three things on the detour.'),
  ('slowing-down-the-mental-chatter', 275, 'Sit with a crossword, a puzzle, or a knitting project for five minutes and let it be the only thing your mind holds.'),
  ('slowing-down-the-mental-chatter', 276, 'Notice a hurry in your speech today and slow your next sentence by half.'),
  ('slowing-down-the-mental-chatter', 277, 'Rub lotion or oil into your hands slowly and give the whole two minutes to the feeling.'),
  ('slowing-down-the-mental-chatter', 278, 'Stand under a streetlight, a porch light, or the moon and watch your shadow for one minute.'),
  ('slowing-down-the-mental-chatter', 279, 'Let a song end before you start the car or open the door.'),
  ('slowing-down-the-mental-chatter', 280, 'Notice the first thing your eyes land on when you walk into a room and stay with it for five breaths.'),
  ('slowing-down-the-mental-chatter', 281, 'Set down your bag, your keys, or your coat at the end of the day and take one breath before the next thing.'),
  ('slowing-down-the-mental-chatter', 282, 'Trace the grain of a wooden table or a floorboard with one finger for one minute.'),
  ('slowing-down-the-mental-chatter', 283, 'Notice a thought about being behind and ask what is actually in front of you right now.'),
  ('slowing-down-the-mental-chatter', 284, 'Sit on a dock, a pier, a riverbank, or the edge of a pool and watch the water move for five minutes.'),
  ('slowing-down-the-mental-chatter', 285, 'Feel the elastic, the buttons, or the zipper of what you are wearing and notice the pressure points.'),
  ('slowing-down-the-mental-chatter', 286, 'Say "thinking" in your head the moment you catch yourself somewhere else during a conversation.'),
  ('slowing-down-the-mental-chatter', 287, 'Look at a stranger''s dog, a passing bike, or a window box and let it be the only thing for ten seconds.'),
  ('slowing-down-the-mental-chatter', 288, 'Notice the pause between the doorbell and opening the door and take one breath in it.'),
  ('slowing-down-the-mental-chatter', 289, 'Walk at the pace of the slowest person on the sidewalk for one block.'),
  ('slowing-down-the-mental-chatter', 290, 'Rest your palms face up on your knees for two minutes and notice the air on them.'),
  ('slowing-down-the-mental-chatter', 291, 'Watch snow melt off a step, a car, or a branch until a drop falls.'),
  ('slowing-down-the-mental-chatter', 292, 'Stand with your eyes closed in a warm shower and count ten drops that land on your face.'),
  ('slowing-down-the-mental-chatter', 293, 'Feel your hips in the seat during a long drive or a long meeting and shift once, slowly, with full attention.'),
  ('slowing-down-the-mental-chatter', 294, 'Notice how many times your mind says "should" this morning and let each one pass without a reply.'),
  ('slowing-down-the-mental-chatter', 295, 'Watch a fly, a moth, or a spider go about its work and let it have your attention for one minute.'),
  ('slowing-down-the-mental-chatter', 296, 'Sit in a library, a chapel, a waiting room, or an empty room and listen to what quiet actually sounds like.'),
  ('slowing-down-the-mental-chatter', 297, 'Leave the dishwasher, the laundry, or the mail for ten minutes and sit with a warm drink first.'),
  ('slowing-down-the-mental-chatter', 298, 'Feel the cool side of the pillow with your cheek and stay there for five breaths.'),
  ('slowing-down-the-mental-chatter', 299, 'Notice a plan for the weekend forming on a Tuesday and let it wait its turn.'),
  ('slowing-down-the-mental-chatter', 300, 'Spend two minutes tracing the shape of a window frame, a picture frame, or a door with your eyes.'),
  ('slowing-down-the-mental-chatter', 301, 'Say a slow "hello" to a thought that keeps knocking and let it sit in the room without giving it a chair.'),
  ('slowing-down-the-mental-chatter', 302, 'Take a walk after the first snow, the first rain, or the first heat wave and notice how the world sounds different.'),
  ('slowing-down-the-mental-chatter', 303, 'Hold a piece of fruit in your hand and notice its weight, temperature, and texture before you eat it.'),
  ('slowing-down-the-mental-chatter', 304, 'Watch the numbers change on a microwave, a treadmill, or a clock and breathe once for each change.'),
  ('slowing-down-the-mental-chatter', 305, 'Let the shower run over the back of your neck for one minute and put all your attention there.'),
  ('slowing-down-the-mental-chatter', 306, 'Write a single word that describes your mind right now, "busy," "foggy," "loud," and leave it at that.'),
  ('slowing-down-the-mental-chatter', 307, 'Feel the give of a cushion, a mattress, or the grass when you sit down on it.'),
  ('slowing-down-the-mental-chatter', 308, 'Notice one thought about the past today and picture it as a page you have already turned.'),
  ('slowing-down-the-mental-chatter', 309, 'Wait for the toaster, the kettle, or the elevator with your hands at your sides and your eyes on one point.'),
  ('slowing-down-the-mental-chatter', 310, 'Pause with your hand on the light switch tonight and take one full breath before the room goes dark.'),
  ('slowing-down-the-mental-chatter', 311, 'Sit on a beach, a lakeshore, or beside a fountain and match your breathing to the rhythm of the water.'),
  ('slowing-down-the-mental-chatter', 312, 'Take a slow breath through your nose and notice whether the air smells like anything at all.'),
  ('slowing-down-the-mental-chatter', 313, 'Notice when your mind replays a conversation from years ago and bring it back to the chair you are sitting in.'),
  ('slowing-down-the-mental-chatter', 314, 'Put your hand flat on the ground outside, soil, grass, pavement, and feel its temperature for ten breaths.'),
  ('slowing-down-the-mental-chatter', 315, 'Walk through a cemetery, a garden, or a quiet park and let the stillness set your pace.'),
  ('slowing-down-the-mental-chatter', 316, 'Listen to a child, a neighbor, or a coworker tell a story and follow only the story, not your reaction to it.'),
  ('slowing-down-the-mental-chatter', 317, 'Untangle a cord, a necklace, or a knot slowly and let the small problem hold your whole mind.'),
  ('slowing-down-the-mental-chatter', 318, 'Notice the light coming through a curtain in the morning and watch it for one full minute.'),
  ('slowing-down-the-mental-chatter', 319, 'Dip your feet in a stream, a pool, or a basin of water and feel the cold climb your ankles.'),
  ('slowing-down-the-mental-chatter', 320, 'Feel the rough and smooth sides of a coin, a key, or a stone with your eyes closed for one minute.'),
  ('slowing-down-the-mental-chatter', 321, 'Let a sneeze, a yawn, or a stretch happen fully instead of cutting it short, and notice the release afterward.'),
  ('slowing-down-the-mental-chatter', 322, 'Stand at the counter while your food heats and count your breaths instead of the seconds.'),
  ('slowing-down-the-mental-chatter', 323, 'Notice a thought that says "not enough time" and take one unhurried breath in reply.'),
  ('slowing-down-the-mental-chatter', 324, 'Sort a handful of coins, buttons, or beads by color and let the sorting be the only thing.'),
  ('slowing-down-the-mental-chatter', 325, 'Watch the last of the daylight leave a room without turning on a lamp.'),
  ('slowing-down-the-mental-chatter', 326, 'Sit in an empty parking lot, an empty field, or an empty room and listen to how far the quiet goes.'),
  ('slowing-down-the-mental-chatter', 327, 'Trace the edge of a leaf, a petal, or a pinecone with your thumb and give it your whole attention.'),
  ('slowing-down-the-mental-chatter', 328, 'Notice the click of a pen, the clack of a keyboard, or the tap of a spoon and let it anchor you for one minute.'),
  ('slowing-down-the-mental-chatter', 329, 'Take the trash out slowly tonight and notice the sky before you come back in.'),
  ('slowing-down-the-mental-chatter', 330, 'Smooth a bedspread, a tablecloth, or a rug with your palms and feel the wrinkles disappear under your hands.'),
  ('slowing-down-the-mental-chatter', 331, 'Let a piece of chocolate, a mint, or a lozenge dissolve completely on your tongue without chewing.'),
  ('slowing-down-the-mental-chatter', 332, 'Sit at a kitchen table with your hands around nothing and count twenty breaths.'),
  ('slowing-down-the-mental-chatter', 333, 'Notice when the chatter is loudest today, morning, afternoon, or night, and take five slow breaths at that hour.'),
  ('slowing-down-the-mental-chatter', 334, 'Whisper the name of each object you touch while you make breakfast: cup, spoon, bowl, milk.'),
  ('slowing-down-the-mental-chatter', 335, 'Walk to a window at the same time each afternoon this week and spend one minute looking out.'),
  ('slowing-down-the-mental-chatter', 336, 'Feel the rain on your palm, or the sun, or the wind, and describe it silently in three words.'),
  ('slowing-down-the-mental-chatter', 337, 'Squeeze a sponge, a towel, or a wet cloth and watch the water leave it, drop by drop.'),
  ('slowing-down-the-mental-chatter', 338, 'Follow the flight of a bird from one branch to the next and let your thoughts fly off with it.'),
  ('slowing-down-the-mental-chatter', 339, 'Sit in the passenger seat, on a bus, or on a train and watch the world go by without narrating it.'),
  ('slowing-down-the-mental-chatter', 340, 'Take one slow breath before you scroll, click, or tap the next thing on a screen this afternoon.'),
  ('slowing-down-the-mental-chatter', 341, 'Notice the smell of a book, a coat, a kitchen, or a car and let it be the whole moment.'),
  ('slowing-down-the-mental-chatter', 342, 'Set a timer for one minute and do nothing at all until it rings.'),
  ('slowing-down-the-mental-chatter', 343, 'Kneel in the garden, the yard, or a planter box and let your hands work the soil for five minutes.'),
  ('slowing-down-the-mental-chatter', 344, 'Notice the pull to check the time and let it pass three times today before you look.'),
  ('slowing-down-the-mental-chatter', 345, 'Stand in the shade on a hot day and feel the difference in temperature on your skin for ten breaths.'),
  ('slowing-down-the-mental-chatter', 346, 'Turn a page, a lock, or a knob slowly enough to hear the sound it makes.'),
  ('slowing-down-the-mental-chatter', 347, 'Notice a thought that wants to plan dinner while you are still at breakfast and return it to the toast in front of you.'),
  ('slowing-down-the-mental-chatter', 348, 'Pause at the mailbox, the porch, or the gate and take three breaths before you walk into the house.'),
  ('slowing-down-the-mental-chatter', 349, 'Feel the cool of a tile floor or the warmth of a wooden one through your socks for one minute.'),
  ('slowing-down-the-mental-chatter', 350, 'Wave to a neighbor, a passing driver, or a stranger and notice the quiet in the seconds after.'),
  ('slowing-down-the-mental-chatter', 351, 'Cup your hands around your ears and listen to the inside of your own head for thirty seconds, then let them drop.'),
  ('slowing-down-the-mental-chatter', 352, 'Notice the moment you finish a task and take one breath before reaching for the next.'),
  ('slowing-down-the-mental-chatter', 353, 'Rest your chin in your hands at a table and watch the room for two minutes without moving.'),
  ('slowing-down-the-mental-chatter', 354, 'Warm your hands over a stove, a fire, or a mug and feel the heat arrive in your fingertips.'),
  ('slowing-down-the-mental-chatter', 355, 'Let an itch, an ache, or a twitch be noticed for five breaths before you respond to it.'),
  ('slowing-down-the-mental-chatter', 356, 'Walk through a store without a list and notice how your mind keeps trying to make one.'),
  ('slowing-down-the-mental-chatter', 357, 'Sit at a bus stop, a bench, or a curb in the fall and count the leaves that land near you in two minutes.'),
  ('slowing-down-the-mental-chatter', 358, 'Notice the light on a wall, a floor, or a ceiling changing as clouds pass over the sun.'),
  ('slowing-down-the-mental-chatter', 359, 'Press your back against a cool wall on a hot day and let the coolness soak in for ten breaths.'),
  ('slowing-down-the-mental-chatter', 360, 'Hold your breath for a count of three at the top of an inhale and notice the stillness before you let it go.'),
  ('slowing-down-the-mental-chatter', 361, 'Let your mind wander for one minute on purpose, then call it back gently and notice how far it went.'),
  ('slowing-down-the-mental-chatter', 362, 'Sit on the ground in a park in summer and feel the grass through your clothes for two minutes.'),
  ('slowing-down-the-mental-chatter', 363, 'Notice the weight of a bag, a coat, or a hat and put it down slowly, feeling the lightness afterward.'),
  ('slowing-down-the-mental-chatter', 364, 'Run a hand through your hair, a pet''s fur, or a fringe of fabric and let the texture hold your attention for a minute.'),
  ('slowing-down-the-mental-chatter', 365, 'Take a breath so slow that you can hear it, and then take another.'),
  ('fostering-gratitude', 1, 'Write down three things that went right today, however small. A warm cup counts.'),
